import { readFile, writeFile } from 'node:fs/promises'
import { legacyPaletteProfiles } from '../packages/components/src/theme/palette.ts'

const destination = new URL(
  '../packages/components/src/styles/legacy-palette.css',
  import.meta.url,
)
const output =
  [
    '/* Generated by scripts/theme-palette.mjs. Edit theme/palette.ts instead. */',
    ...legacyPaletteProfiles.map(
      ({ selector, declarations }) =>
        `${selector} {\n${Object.entries(declarations)
          .map(([name, value]) => `  ${name}: ${value};`)
          .join('\n')}\n}`,
    ),
  ].join('\n\n') + '\n'

if (process.argv.includes('--check')) {
  if ((await readFile(destination, 'utf8')) !== output)
    throw new Error(
      'Legacy palette is stale. Run node scripts/theme-palette.mjs',
    )
} else {
  await writeFile(destination, output)
}
